/// <summary>
/// Extension class to override the Print Management settings
/// </summary>
[ExtensionOf(classStr(SrsReportRunPrinter))]
internal final class METSrsReportRunPrinter_Extension
{
    

}

Method.Source:
    /// <summary>
    /// This method is COC'ed to override the print mangement settings (initially for overriding To Email address of Purchase confirmation report)
    /// </summary>
    public void printReport()
    {
        #OCCRetryCount
        SrsReportDataContract contract = reportContract;
        boolean               updatePOSentFlag;
        RefRecId              purchTableRecId;

        //check if print method is Email and contract type is Purchase order confirmation (we can add in condition for a particular report as well )
        if(contract && SRSPrintMediumType::Email && contract.parmRdpContract() as PurchPurchaseOrderContract && METVendParameters::find().IGHPOHeadEmailEDIAutoDefConfirmOverride)//MPJ_27166_BuyPOFSDEnhancements
        {
            PurchPurchaseOrderContract purchConfirmContract  = contract.parmRdpContract() as PurchPurchaseOrderContract;
            
            VendPurchOrderJour  metVendPurchOrderJourStd;
            PurchTable          metpurchTableStd;
            METPurchTable       metPurchTable;

            select firstonly PurchId from metVendPurchOrderJourStd
                    where metVendPurchOrderJourStd.RecId == purchConfirmContract.parmRecordId()
                join recid from metpurchTableStd
                    where metpurchTableStd.PurchId == metVendPurchOrderJourStd.PurchId
                join POSubMode from metpurchTable
                    where metPurchTable.PurchTable == metpurchTableStd.Recid;

            purchTableRecId = metpurchTableStd.RecId;
            //update To Email address based on Vendor Site settings of the purchase order
            //Modified by kavya for MPJ_19962_MDRPOTransactionalMissingFields - part 2 --> Begin
            if(purchTableRecId && METVendSiteSettingsSetup::existsPOVendSiteRecord(metVendPurchOrderJourStd.PurchId))
            {
                if(this.isFirstConfirmation(metVendPurchOrderJourStd))// MPJ_27166_BuyPOFSDEnhancements
                {
                    if( metPurchTable.POSubMode != METConstants::emptyString)
                    {
                        updatePOSentFlag = true;
                        if(metPurchTable.POIHGEmailEDIAddress)
                        {
                            this.updateToEmailAddress(metPurchTable.POIHGEmailEDIAddress);
                        }
                        else
                        {
                            this.updateToEmailAddress(METVendSiteSettingsSetup::getPurchOrderEmailAddress(metVendPurchOrderJourStd.PurchId));
                        }
                        

                        if(metPurchTable.POSubMode == METConstants::EDI || metPurchTable.POSubMode == METConstants::None) 
                        {
                            this.skipSendingEmail();
                        }
                    }
                    else
                    {
                        throw error("@MET:METPOSubModeErrorMsg");
                    }
                }
                // MPJ_27166_BuyPOFSDEnhancements
                else
                {
                    if( metPurchTable.POChngSubMode != METConstants::emptyString)
                    {
                        if(metPurchTable.POIHGEmailEDIAddressChnge)
                        {
                            updatePOSentFlag = true;
                            this.updateToEmailAddress(metPurchTable.POIHGEmailEDIAddressChnge);
                        }
                        else
                        {
                            updatePOSentFlag = true;
                            this.updateToEmailAddress(METVendSiteSettingsSetup::getPurchOrderEmailAddress(metVendPurchOrderJourStd.PurchId));
                        }                        
                    }
                    else if(metPurchTable.POChngSubMode == METConstants::EDI || metPurchTable.POChngSubMode == METConstants::None)
                    {
                        updatePOSentFlag = true;
                        this.skipSendingEmail();
                    }
                    else
                    {
                        throw error("@MET:METPOSubModeErrorMsg");
                    }

                }
                // MPJ_27166_BuyPOFSDEnhancements
            }
            //Modified by kavya for MPJ_19962_MDRPOTransactionalMissingFields - part 2 --> End
        }

        next printReport();

        if(updatePOSentFlag && purchTableRecId)
        {
            try
            {
                ttsbegin;
                METPurchTable metPurchTable = METPurchTable::findByPurchTable(purchTableRecId,true);
                metPurchTable.POSentFlag = NoYes::Yes;
                metPurchTable.update();
                ttscommit;
            }
            catch(Exception::UpdateConflict)
            {
                error("@MET:METPOUpdateConflict");
                throw Exception::UpdateConflictNotRecovered;
            }
            catch(Exception::Deadlock)
            {
                if (xSession::currentRetryCount() >= #RetryNum)
                {
                    throw Exception::UpdateConflictNotRecovered;
                }
                retry;
            }
            catch(Exception::Error)
            {
                error("@MET:METPOUpdateConflict");
            }
            
        }
        
    }

private void updateToEmailAddress(METEmailAddress _toEmailAddresses)
{
    if(_toEmailAddresses)
    {
        SrsReportEMailDataContract  emailContract = printSettings.parmEMailContract();
        emailContract.parmTo(_toEmailAddresses);
    }
}

/// <summary>
/// check whether PO confirmation is the first one. Assume that document number doesn't exceed 99 for one PO
/// MPJ_27166_BuyPOFSDEnhancements
/// <param name = "_vendPurchOrderJour"></param>
/// </summary>
private boolean isFirstConfirmation(VendPurchOrderJour  _vendPurchOrderJour)
{
    str lastTwoChar = subStr(_vendPurchOrderJour.PurchOrderDocNum,strLen(_vendPurchOrderJour.PurchOrderDocNum),-2);
    switch(lastTwoChar)
    {
        case '11','21','31','41','51','61','71','81','91':
            return false;
            break;
        default:
            str docVersion  = subStr(_vendPurchOrderJour.PurchOrderDocNum,strLen(_vendPurchOrderJour.PurchOrderDocNum),-1);
            if(docVersion=='1')
            {
                return true;
            }
            break;
    }
    
    return false;
}
